public class Cleanup(IServiceScopeFactory sf, ILogger<Cleanup> log) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken ct) {
        using var timer = new PeriodicTimer(TimeSpan.FromMinutes(5));
        while (await timer.WaitForNextTickAsync(ct)) {
            try { using var s = sf.CreateScope();
                  await s.ServiceProvider.GetRequiredService<AppDb>().PurgeAsync(ct); }
            catch (Exception ex) when (ex is not OperationCanceledException)
            { log.LogError(ex, "Cleanup failed"); }
        }
    }
}

